if (numberOfChecks <= 0) {
        return false;
    }

    int insideCount = 0;
    for (int i = 0; i < numberOfChecks; ++i) {
        Vec3d direction = randomDirection();
        Vec3d rayOrigin(p.x(), p.y(), p.z());
        Vec3d rayEnd = rayOrigin + direction; // Ray extends infinitely in this direction

        // Create a segment for the ray query (using CGAL's segment)
        K::Segment_3 ray_query(K::Point_3(rayOrigin.x(), rayOrigin.y(), rayOrigin.z()),
                               K::Point_3(rayEnd.x(), rayEnd.y(), rayEnd.z()));

        std::list<Tree::Primitive_id> intersectedTriangles;
        tree.all_intersected_primitives(ray_query, std::back_inserter(intersectedTriangles));

        // Count intersections (odd or even)
        bool oddIntersections = (intersectedTriangles.size() % 2) != 0;
        if (oddIntersections) {
            insideCount++;
        }
    }

    // If more than half the rays intersect an odd number of times, the point is inside
    return insideCount > numberOfChecks / 2;

