int insideCount = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    Vec3d direction = randomDirection();
    // Convert Vec3d to CGAL's Point_3 for ray casting
    K::Point_3 origin(p.x(), p.y(), p.z());
    K::Vector_3 dir(direction.x(), direction.y(), direction.z());
    K::Ray_3 ray(origin, dir);

    std::list<Tree::Primitive_id> intersectedTriangles;
    tree.all_intersected_primitives(ray, std::back_inserter(intersectedTriangles));

    if ((intersectedTriangles.size() % 2) != 0) {
        insideCount++;
    }
}

return insideCount > numberOfChecks / 2;

