action.code:
if (numberOfChecks <= 0) {
        return false;
    }

    int insideCount = 0;
    for (int i = 0; i < numberOfChecks; ++i) {
        Vec3d direction = randomDirection();
        Vec3d rayOrigin(p.x(), p.y(), p.z());
        Vec3d rayEnd = rayOrigin + direction;

        // Use Tree's kernel type (assumed to be K)
        using K = typename Tree::Traits::Kernel;
        K::Ray_3 ray(K::Point_3(rayOrigin.x(), rayOrigin.y(), rayOrigin.z()),
                     K::Vector_3(direction.x(), direction.y(), direction.z()));

